import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import http from 'node:http';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SERVER = path.join(HERE, '..', 'server.mjs');
const WORK = fs.mkdtempSync(path.join(HERE, 'w-'));

function run(env) {
  const child = spawn(process.execPath, [SERVER], { cwd: WORK, env: { ...process.env, ...env } });
  let out = '';
  let err = '';
  child.stdout.on('data', (d) => { out += d; });
  child.stderr.on('data', (d) => { err += d; });
  const exited = new Promise((r) => child.on('exit', (code) => r(code)));
  const ready = new Promise((resolve, reject) => {
    child.stdout.on('data', () => { const m = /:(\d+)\n$/.exec(out); if (m) resolve(Number(m[1])); });
    child.on('exit', () => reject(new Error('exited')));
  });
  return { child, exited, ready, io: () => ({ out, err }) };
}

function req(port, method, p, { headers = {}, body } = {}) {
  return new Promise((resolve, reject) => {
    const r = http.request({ host: '127.0.0.1', port, method, path: p, headers }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        const text = Buffer.concat(chunks).toString();
        let json; try { json = JSON.parse(text); } catch { json = undefined; }
        resolve({ status: res.statusCode, type: res.headers['content-type'], text, json });
      });
    });
    r.on('error', reject);
    if (body !== undefined) r.write(body);
    r.end();
  });
}
const J = { 'Content-Type': 'application/json' };
const post = (port, obj, headers = J) => req(port, 'POST', '/api/bookings', { headers, body: typeof obj === 'string' ? obj : JSON.stringify(obj) });
const B = (o) => ({ room: 'Aurora', title: 'x', date: '2026-11-03', start: '09:00', end: '10:00', ...o });

test('startup failures', async () => {
  for (const PORT of ['abc', '65536', ' 1', '-1']) {
    const s = run({ PORT });
    assert.equal(await s.exited, 1, PORT);
    assert.equal(s.io().out, '');
    assert.match(s.io().err, /^[^\n]+\n$/);
  }
  fs.mkdirSync(path.join(WORK, 'adir'));
  fs.writeFileSync(path.join(WORK, 'empty.json'), '');
  fs.writeFileSync(path.join(WORK, 'bad.json'), JSON.stringify({ nextId: 1, bookings: [B({ id: 1 })] }));
  fs.writeFileSync(path.join(WORK, 'extra.json'), JSON.stringify({ nextId: 2, bookings: [{ ...B({ id: 1 }), x: 1 }] }));
  for (const DATA_FILE of ['adir', 'empty.json', 'bad.json', 'extra.json']) {
    const s = run({ PORT: '0', DATA_FILE });
